            half max_val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2];
            for (int64_t i = 1; i < dim2; i++) {
                half val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2 + i];
                max_val = __hgt__(val, max_val) ? val : max_val;
            }
            output[batch_idx * dim1 + dim1_idx] = max_val;
        }
    } else if (reduce_dim == 1) {
        // Reduce over dim1 (middle dimension)
        int64_t batch_idx = tid / dim2;
        int64_t dim2_idx = tid % dim2;

        if (batch_idx < batch_size && dim2_idx < dim2) {
            half max_val = input[batch_idx * dim1 * dim2 + dim2_idx];
            for (int64_t i = 1; i < dim1; i++) {
                half val = input[batch_idx * dim1 * dim2 + i * dim2 + dim2_idx];
                max_val = __hgt__(val, max_val) ? val : max_val;
            }
            output[batch_idx * dim2 + dim2_idx] = max_val;
        }
    }
}

